const staticData = $getWorkflowStaticData('global');
if (!staticData.media_collections) staticData.media_collections = [];
if (!staticData.media_items) staticData.media_items = [];
if (!staticData.next_collection_id) staticData.next_collection_id = 1;
if (!staticData.next_item_id) staticData.next_item_id = 1;

const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;
const action = body.action || 'ping';

function now() { return new Date().toISOString(); }

function extractAltFromUrl(url) {
  try {
    var filename;
    try {
      filename = new URL(url).pathname.split('/').pop();
    } catch (e) {
      var parts = url.split('/');
      filename = parts[parts.length - 1] || '';
    }
    var name = filename.replace(/\.[^.]+$/, '');
    return name.replace(/[-_]+/g, ' ').replace(/\b\w/g, function(c) { return c.toUpperCase(); });
  } catch (e) { return ''; }
}

function detectMediaType(url) {
  if (/youtube\.com\/watch|youtu\.be\//i.test(url)) return 'youtube';
  return 'image';
}

function isValidUrl(str) {
  try { new URL(str); return true; } catch (e) { return /^https?:\/\/.+/i.test(str); }
}

let result = {};

switch (action) {
  case 'ping':
    result = { ok: true, message: 'Media Library webhook reachable', received_at: now() };
    break;

  case 'create_collection': {
    const name = (body.name || '').trim();
    if (!name) { result = { error: 'Collection name is required.' }; break; }
    const col = {
      id: staticData.next_collection_id++,
      name: name,
      description: (body.description || '').trim(),
      created_at: now()
    };
    staticData.media_collections.push(col);
    result = { ok: true, collection: col };
    break;
  }

  case 'list_collections': {
    const cols = staticData.media_collections.map(function(col) {
      const itemCount = staticData.media_items.filter(function(i) { return i.collection_id === col.id; }).length;
      return { id: col.id, name: col.name, description: col.description, created_at: col.created_at, item_count: itemCount };
    });
    result = { collections: cols };
    break;
  }

  case 'delete_collection': {
    const colId = parseInt(body.collection_id);
    if (!colId) { result = { error: 'collection_id is required.' }; break; }
    const idx = staticData.media_collections.findIndex(function(c) { return c.id === colId; });
    if (idx === -1) { result = { error: 'Collection not found.' }; break; }
    staticData.media_collections.splice(idx, 1);
    staticData.media_items = staticData.media_items.filter(function(i) { return i.collection_id !== colId; });
    result = { ok: true };
    break;
  }

  case 'add_items': {
    const colId = parseInt(body.collection_id);
    if (!colId) { result = { error: 'collection_id is required.' }; break; }
    const col = staticData.media_collections.find(function(c) { return c.id === colId; });
    if (!col) { result = { error: 'Collection not found.' }; break; }
    const urls = body.urls;
    if (!Array.isArray(urls) || urls.length === 0) { result = { error: 'urls array is required and must not be empty.' }; break; }
    const added = [];
    const errors = [];
    for (let i = 0; i < urls.length; i++) {
      const entry = urls[i];
      const url = (typeof entry === 'string') ? entry.trim() : (entry.url || '').trim();
      if (!url) { errors.push('Empty URL at position ' + (i + 1)); continue; }
      if (!isValidUrl(url)) { errors.push('Invalid URL: ' + url); continue; }
      const item = {
        id: staticData.next_item_id++,
        collection_id: colId,
        url: url,
        alt_text: (typeof entry === 'object' && entry.alt_text) ? entry.alt_text.trim() : extractAltFromUrl(url),
        media_type: (typeof entry === 'object' && entry.media_type) ? entry.media_type.trim() : detectMediaType(url),
        created_at: now()
      };
      staticData.media_items.push(item);
      added.push(item);
    }
    result = { ok: true, added_count: added.length, items: added, errors: errors.length ? errors : undefined };
    break;
  }

  case 'list_items': {
    const colId = parseInt(body.collection_id);
    if (!colId) { result = { error: 'collection_id is required.' }; break; }
    const items = staticData.media_items.filter(function(i) { return i.collection_id === colId; });
    result = { items: items };
    break;
  }

  case 'delete_item': {
    const colId = parseInt(body.collection_id);
    const itemId = parseInt(body.item_id);
    if (!colId || !itemId) { result = { error: 'collection_id and item_id are required.' }; break; }
    const idx = staticData.media_items.findIndex(function(i) { return i.id === itemId && i.collection_id === colId; });
    if (idx === -1) { result = { error: 'Item not found.' }; break; }
    staticData.media_items.splice(idx, 1);
    result = { ok: true };
    break;
  }

  default:
    result = { error: 'Unknown action: ' + action };
}

return [{ json: result }];
